// CloudNoiseTextures.js - builds the cloud noise textures once per page.
//
// Lazy: nothing runs until the first visible cloud layer asks for the textures
// (requestCloudNoiseTextures). The bytes are generated by a small pool of Web
// Workers (CloudNoiseWorker.js) over slabs of z-slices; the main thread only
// copies the slabs into place and creates the Three.js textures. One shared
// promise: every caller gets the same textures, and they live for the page
// (they are about 9 MB of GPU memory and identical for every sitch).
//
// No Worker (Jest, or a failed spawn): the same generator runs on the main
// thread, so the result is identical, only slower.

import {Data3DTexture, DataTexture, LinearFilter, LinearMipmapLinearFilter, NearestFilter, RedFormat, RGBAFormat, RepeatWrapping, UnsignedByteType} from "three";
import {
    BLUE_NOISE_SIZE,
    DETAIL_SIZE,
    generateBlueNoise,
    generateDetail,
    generateShapeSlices,
    generateWeather,
    NOISE_SEED,
    NOISE_VERSION,
    SHAPE_SIZE,
    shapeContext,
    WEATHER_SIZE,
} from "./CloudNoise";

let texturesPromise = null;
let textures = null;

export function cloudNoiseTextures() {
    return textures;
}

function make3DTexture(bytes, size, name) {
    const texture = new Data3DTexture(bytes, size, size, size);
    texture.name = name;
    texture.format = RGBAFormat;
    texture.type = UnsignedByteType;
    // Mipmapped: the march reads far samples from coarser levels (textureLod).
    texture.minFilter = LinearMipmapLinearFilter;
    texture.magFilter = LinearFilter;
    texture.wrapS = texture.wrapT = texture.wrapR = RepeatWrapping;
    texture.generateMipmaps = true;
    texture.unpackAlignment = 1;
    texture.needsUpdate = true;
    return texture;
}

function makeBlueNoiseTexture(bytes) {
    const texture = new DataTexture(bytes, BLUE_NOISE_SIZE, BLUE_NOISE_SIZE, RedFormat, UnsignedByteType);
    texture.name = "cloudBlueNoise";
    texture.minFilter = NearestFilter;
    texture.magFilter = NearestFilter;
    texture.wrapS = texture.wrapT = RepeatWrapping;
    texture.generateMipmaps = false;
    texture.unpackAlignment = 1;
    texture.needsUpdate = true;
    return texture;
}

function workerCount() {
    const cores = (typeof navigator !== "undefined" && navigator.hardwareConcurrency) || 4;
    return Math.max(1, Math.min(8, cores - 1));
}

function runOnMainThread() {
    const context = shapeContext(NOISE_SEED);
    return {
        shape: generateShapeSlices(SHAPE_SIZE, 0, SHAPE_SIZE, NOISE_SEED, context),
        detail: generateDetail(DETAIL_SIZE, NOISE_SEED),
        weather: generateWeather(WEATHER_SIZE, NOISE_SEED),
        blueNoise: generateBlueNoise(BLUE_NOISE_SIZE, NOISE_SEED),
    };
}

function runInWorkers() {
    return new Promise((resolve, reject) => {
        const count = workerCount();
        const workers = [];
        const shape = new Uint8Array(SHAPE_SIZE * SHAPE_SIZE * SHAPE_SIZE * 4);
        const result = {shape, detail: null, weather: null, blueNoise: null};
        // Small jobs first in the queue, so they overlap the long shape slabs.
        const jobs = [{job: "weather", size: WEATHER_SIZE, seed: NOISE_SEED}, {job: "detail", size: DETAIL_SIZE, seed: NOISE_SEED},
            {job: "blueNoise", size: BLUE_NOISE_SIZE, seed: NOISE_SEED}];
        const slab = Math.ceil(SHAPE_SIZE / (count * 2));
        for (let z0 = 0; z0 < SHAPE_SIZE; z0 += slab) {
            jobs.push({job: "shape", size: SHAPE_SIZE, z0, z1: Math.min(SHAPE_SIZE, z0 + slab), seed: NOISE_SEED});
        }
        let pending = jobs.length;
        let failed = false;
        const finish = (error) => {
            for (const worker of workers) worker.terminate();
            if (error) reject(error); else resolve(result);
        };
        const next = (worker) => {
            const job = jobs.shift();
            if (job) worker.postMessage(job);
        };
        for (let index = 0; index < count; index++) {
            let worker;
            try {
                worker = new Worker(new URL("../workers/CloudNoiseWorker.js", import.meta.url));
            } catch (error) {
                finish(error);
                return;
            }
            workers.push(worker);
            worker.onmessage = (event) => {
                if (failed) return;
                const message = event.data;
                if (message.error) {
                    failed = true;
                    finish(new Error(message.error));
                    return;
                }
                if (message.job === "shape") {
                    shape.set(message.bytes, message.z0 * SHAPE_SIZE * SHAPE_SIZE * 4);
                } else {
                    result[message.job] = message.bytes;
                }
                if (--pending === 0) finish(null);
                else next(worker);
            };
            // The script may not load at all: a rebuild deletes the old chunk from under an open tab.
            worker.onerror = (event) => {
                if (failed) return;
                failed = true;
                finish(new Error("Cloud noise worker failed: " + (event.message ?? event.type)));
            };
            next(worker);
        }
    });
}

// The shared promise of the {shape, detail, weather} Data3DTextures and the blue-noise DataTexture.
export function requestCloudNoiseTextures() {
    if (texturesPromise) return texturesPromise;
    const started = (typeof performance !== "undefined" ? performance.now() : Date.now());
    const generate = typeof Worker === "undefined"
        ? Promise.resolve().then(runOnMainThread)
        : runInWorkers().catch(error => {
            console.warn("Cloud noise: workers unavailable, generating on the main thread.", error);
            return runOnMainThread();
        });
    texturesPromise = generate.then(bytes => {
        textures = {
            shape: make3DTexture(bytes.shape, SHAPE_SIZE, "cloudShapeNoise"),
            detail: make3DTexture(bytes.detail, DETAIL_SIZE, "cloudDetailNoise"),
            weather: make3DTexture(bytes.weather, WEATHER_SIZE, "cloudWeatherNoise"),
            blueNoise: makeBlueNoiseTexture(bytes.blueNoise),
            version: NOISE_VERSION,
            milliseconds: (typeof performance !== "undefined" ? performance.now() : Date.now()) - started,
        };
        return textures;
    });
    return texturesPromise;
}
